var WHITEEEL_WORDS = {
  W001: ["ตี้เจียงฮาย ใกล้เจียงแสน มีหนองน้ำกว้างหลวง จื่อหนองหล่ม", "ตี้เจียงฮาย ใกล้เจียงแสน มีหนองน้ำกว้างหลวง จื่อหนองหล่ม", "In Chiang Rai, near Chiang Saen, there is a wide marsh called Nong Lom."],
  W002: ["คนเฒ่าคนแก่เล่าว่า ตี้เพ้เกยมีเมืองหลวงตั้งอยู่", "คนเฒ่าคนแก่เล่าว่า ตี้เพ้เกยมีเมืองหลวงตั้งอยู่", "The old people say that a great city once stood here."],
  W003: ["นี่เป๋นเรื่องของป๋าเหยี่ยนเผือก ละก่อเมืองตี้ล่มจ๋มลงไป", "นี่เป๋นเรื่องของป๋าเหยี่ยนเผือก ละก่อเมืองตี้ล่มจ๋มลงไป", "This is the story of the white eel, and how that city sank."],
  W004: ["สมัยก่อน เจ้าชายสิงหนวัติเดินทางลุ๊กตี้ไกล๋มา เพื่อเซาะตี้ตั้งเก๊าแป๋งเมือง", "สมัยก่อน เจ้าชายสิงหนวัติเดินทางลุ๊กตี้ไกล๋มา เพื่อเซาะตี้ตั้งเก๊าแป๋งเมือง", "Long, long ago, Prince Singhanavati came from far away, looking for a place to build a city."],
  W005: ["ตี้ฮิมแม่น้ำกก มีพราหมณ์คนหนึ่งมาป๊ะ", "ตี้ฮิมแม่น้ำกก มีพราหมณ์คนหนึ่งมาป๊ะ", "By the Kok river, a Brahman came to meet him."],
  W006: ["พราหมณ์บอกว่า ตั้งเก๊าแป๋งเมืองตี้เพ้เต๊อะ เมืองจะฮุ่งเฮือง", "พราหมณ์บอกว่า ตั้งเก๊าแป๋งเมืองตี้เพ้เต๊อะ เมืองจะฮุ่งเฮือง", "\"Build your city here,\" said the Brahman, \"and it will grow rich.\""],
  W007: ["ขอเพียงอย่างเดียว หื้อมีใจ๋ฮักคน ละก่อสัตว์ตึงหลาย", "ขอเพียงอย่างเดียว หื้อมีใจ๋ฮักคน ละก่อสัตว์ตึงหลาย", "\"Only this: have a heart that loves people and animals.\""],
  W008: ["แล้วพราหมณ์ก่อเตียวจากไป คนของเจ้าชายตี้โตยไป หันเขาหายวับไป", "แล้วพราหมณ์ก่อเตียวจากไป คนของเจ้าชายตี้โตยไป หันเขาหายวับไป", "Then he walked away, and the prince's men who followed him saw him vanish."],
  W009: ["พราหมณ์คนนั้นตี้แต้คือพญานาค จื่อพันธุนาคราช", "พราหมณ์คนนั้นตี้แต้คือพญานาค จื่อพันธุนาคราช", "The Brahman was really a naga, the naga king Phanthu."],
  W010: ["พญานาคปิ๊กเป๋นร่างเดิม แล้วขุดคูน้ำล้อมรอบตี้แป๋งเมือง", "พญานาคปิ๊กเป๋นร่างเดิม แล้วขุดคูน้ำล้อมรอบตี้แป๋งเมือง", "In his own shape, he dug a moat all around the city's land."],
  W011: ["เมืองจึงได้จื่อตามเปิ้นตึงสอง คือนาคพันธุ์ ละก่อสิงหนวัติ มีจื่อเต๋มว่า โยนกนาคพันธุ์สิงหนวัติ", "เมืองจึงได้จื่อตามเปิ้นตึงสอง คือนาคพันธุ์ ละก่อสิงหนวัติ มีจื่อเต๋มว่า โยนกนาคพันธุ์สิงหนวัติ", "So the city was named for them both, the naga Phanthu and Singhanavati: Yonok Nakaphan Singhanavati."],
  W012: ["ต่อมา ผู้คนฮ้องเมืองนี้ว่าโยนกนคร", "ต่อมา ผู้คนฮ้องเมืองนี้ว่าโยนกนคร", "Later, people called it Yonok Nakhon."],
  W013: ["เมืองโยนกฮุ่งเฮือง ละก่อยิ่งใหญ่", "เมืองโยนกฮุ่งเฮือง ละก่อยิ่งใหญ่", "Yonok grew rich, and great."],
  W014: ["หลังสมัยพรหมกุมารกับจ๊างเผือกไปเมินแล้ว มีกษัตริย์ครองเมืองสืบต่อกั๋นมาถึงสี่สิบห้าองค์", "หลังสมัยพรหมกุมารกับจ๊างเผือกไปเมินแล้ว มีกษัตริย์ครองเมืองสืบต่อกั๋นมาถึงสี่สิบห้าองค์", "Long after the days of Phrom and his white elephant, forty-five kings had ruled it, one after another."],
  W015: ["องค์สุดท้ายคือพระองค์มหาไชยชนะ อายุเจ็ดสิบปี๋", "องค์สุดท้ายคือพระองค์มหาไชยชนะ อายุเจ็ดสิบปี๋", "The last of them was King Mahachaichana. He was seventy years old."],
  W016: ["ตี้นอกเวียง มีแม่อุ้ยแม่ฮ๊างคนหนึ่งเปิ้นอยู่คนเดียว", "ตี้นอกเวียง มีแม่อุ้ยแม่ฮ๊างคนหนึ่งเปิ้นอยู่คนเดียว", "At the edge of the city lived an old widow, all alone."],
  W017: ["แม่อุ้ยบ่ามีลูก บ่ามีหลาน", "แม่อุ้ยบ่ามีลูก บ่ามีหลาน", "She had no children, and no grandchildren."],
  W018: ["ละก่อบ่ามีไผในเมืองปั๋นอะหยั๋งหื้อเปิ้นเลย", "ละก่อบ่ามีไผในเมืองปั๋นอะหยั๋งหื้อเปิ้นเลย", "And no one in the city ever shared anything with her."],
  W019: ["วันหนึ่ง คนตี้ไปเซาะป๋าในน้ำกก หันป๋าเหยี่ยนเผือก", "วันหนึ่ง คนตี้ไปเซาะป๋าในน้ำกก หันป๋าเหยี่ยนเผือก", "One day, people fishing in the Kok river saw a white eel."],
  W020: ["ตั๋วยาวเต้าต้นตาล ยาวถึงเจ็ดวา", "ตั๋วยาวเต้าต้นตาล ยาวถึงเจ็ดวา", "It was as thick as a sugar palm, and seven wa long."],
  W021: ["หมู่เขาหยั๊บมันได้ แล้วก่อลากไปถวายหื้อเจ้าเมือง", "หมู่เขาหยั๊บมันได้ แล้วก่อลากไปถวายหื้อเจ้าเมือง", "They caught it, and dragged it all the way to the king."],
  W022: ["เจ้าเมืองสั่งหื้อตัดเป๋นก้อม แจกจาวเมืองหื้อกิ๋นกั๋นกู๊ผู้กู๊คน", "เจ้าเมืองสั่งหื้อตัดเป๋นก้อม แจกจาวเมืองหื้อกิ๋นกั๋นกู๊ผู้กู๊คน", "The king had it cut into pieces, and shared out to every house in the city."],
  W023: ["กู๊เฮือนยะกิ๋น กลิ่นหอมไปไขว่เมือง กู๊ตี้กู๊ตาง", "กู๊เฮือนยะกิ๋น กลิ่นหอมไปไขว่เมือง กู๊ตี้กู๊ตาง", "Every kitchen cooked it, and the whole city smelled of it."],
  W024: ["มีเฮือนเดียวตี้บ่าได้คือเฮือนของแม่อุ้ยแม่ฮ๊าง", "มีเฮือนเดียวตี้บ่าได้คือเฮือนของแม่อุ้ยแม่ฮ๊าง", "Only one house got none: the old widow's."],
  W025: ["เมื่อแลงวันนั้น มีจายหนุ่มคนหนึ่งมาตี้เฮือนของแม่อุ้ย แต่บ่ามีไผฮู้เลยว่าลุ๊กตางใดมา", "เมื่อแลงวันนั้น มีจายหนุ่มคนหนึ่งมาตี้เฮือนของแม่อุ้ย แต่บ่ามีไผฮู้เลยว่าลุ๊กตางใดมา", "That evening, a young man came to her house. No one knew where he came from."],
  W026: ["เปิ้นขอพักค้างคืน แม่อุ้ยเอาข้าวเอาน้ำมาหื้อ แต่เปิ้นบ่ากิ๋นอะหยั๋งสักอย่าง", "เปิ้นขอพักค้างคืน แม่อุ้ยเอาข้าวเอาน้ำมาหื้อ แต่เปิ้นบ่ากิ๋นอะหยั๋งสักอย่าง", "He asked to stay the night. She gave him rice and water, but he ate nothing."],
  W027: ["เปิ้นถามว่าจาวเมืองเปิ้นกิ๋นอะหยั๋งกั๋นหอมไปตึงเมือง", "เปิ้นถามว่าจาวเมืองเปิ้นกิ๋นอะหยั๋งกั๋นหอมไปตึงเมือง", "\"What is the whole city eating?\" he asked. \"It smells so good.\""],
  W028: ["แม่อุ้ยตอบว่า ป๋าเหยี่ยนเผือกตั๋วหลวง เขาแจกกั๋นกิ๋นกู๊เฮือน", "แม่อุ้ยตอบว่า ป๋าเหยี่ยนเผือกตั๋วหลวง เขาแจกกั๋นกิ๋นกู๊เฮือน", "\"A big white eel,\" she said. \"They shared it to every house.\""],
  W029: ["แล้วแม่อุ้ยได้กิ๋นโตยก่อ", "แล้วแม่อุ้ยได้กิ๋นโตยก่อ", "\"And did you eat some?\""],
  W030: ["แม่อุ้ยเฒ่าแล้ว ซ้ำเป๋นแม่ฮ๊าง บ่ามีลูกบ่ามีหลาน ไผเขาจะหื้อแม่อุ้ยกิ๋น", "แม่อุ้ยเฒ่าแล้ว ซ้ำเป๋นแม่ฮ๊าง บ่ามีลูกบ่ามีหลาน ไผเขาจะหื้อแม่อุ้ยกิ๋น", "\"I am old, a widow, with no children or grandchildren. Who would give me any?\""],
  W031: ["ดีแล้วตี้แม่อุ้ยบ่าได้กิ๋น จะไปไข้ได้ไข้กิ๋นเน้อ", "ดีแล้วตี้แม่อุ้ยบ่าได้กิ๋น จะไปไข้ได้ไข้กิ๋นเน้อ", "\"Good that you did not,\" he said. \"Do not wish you had.\""],
  W032: ["เขาบอกว่าหลานจะออกไปตางนอกสักกำ", "เขาบอกว่าหลานจะออกไปตางนอกสักกำ", "\"I am going out for a while,\" he said."],
  W033: ["คืนนี้ถ้ามีเหตุอะหยั๋งเกิดขึ้น ถ้าบ่าหันหน้าหลาน บะดีลงจากเฮือนไปตางใด", "คืนนี้ถ้ามีเหตุอะหยั๋งเกิดขึ้น ถ้าบ่าหันหน้าหลาน บะดีลงจากเฮือนไปตางใด", "\"Whatever happens tonight, do not come down from your house until you see my face again.\""],
  W034: ["แล้วเขาก่อเตียวหายไปในความมืด ลงไปตางน้ำ", "แล้วเขาก่อเตียวหายไปในความมืด ลงไปตางน้ำ", "Then he went off into the dark, down toward the river."],
  W035: ["พอตะวันต๊ก แม่อุ้ยได้ยินเสียงดังสนั่นปั่นปื้น เหมือนเมืองตึงเมืองจะเตลง", "พอตะวันต๊ก แม่อุ้ยได้ยินเสียงดังสนั่นปั่นปื้น เหมือนเมืองตึงเมืองจะเตลง", "After the sun went down, she heard a roar, as if the whole city would break apart."],
  W036: ["แม่อุ้ยกั๋วขนาด แต่นึกถึงกำของจายหนุ่ม ก่อเลยปิ๊กเข้าไปหลับเหีย", "แม่อุ้ยกั๋วขนาด แต่นึกถึงกำของจายหนุ่ม ก่อเลยปิ๊กเข้าไปหลับเหีย", "She was afraid. But she remembered his words, and went back to bed."],
  W037: ["ต๋อนเตี่ยงคืน เสียงดังขึ้นมาแห๋ม แม่อุ้ยลุ๊กไปตี้ประตู๋ แต่นึกถึงกำสั่งนั้น เลยบะออกไปซักกำ", "ต๋อนเตี่ยงคืน เสียงดังขึ้นมาแห๋ม แม่อุ้ยลุ๊กไปตี้ประตู๋ แต่นึกถึงกำสั่งนั้น เลยบะออกไปซักกำ", "At midnight it came again. She went to the door, but remembered his words, and did not go out."],
  W038: ["ใกล้แจ้ง เสียงเตื้อตี้สามก่อดังขึ้น ดังเหลือกู๊เตื้อ", "ใกล้แจ้ง เสียงเตื้อตี้สามก่อดังขึ้น ดังเหลือกู๊เตื้อ", "Before dawn came the third, the loudest of all."],
  W039: ["แม่อุ้ยออกไปตี้ขั้นใด แต่บ่าได้ลงไป", "แม่อุ้ยออกไปตี้ขั้นใด แต่บ่าได้ลงไป", "She went to the top of her stairs, and did not go down."],
  W040: ["บะกองฟ้าแจ้ง แม่อุ้ยผ่อไปตางเหนือ ตางใต้", "บะกองฟ้าแจ้ง แม่อุ้ยผ่อไปตางเหนือ ตางใต้", "When the sun came up, she looked to the north and to the south."],
  W041: ["เมืองหายแซ็บหมดปอตกปอเสี้ยง มีก้าน้ำ", "เมืองหายแซ็บหมดปอตกปอเสี้ยง มีก้าน้ำ", "The city was gone. There was only water,"],
  W042: ["เหลือก้าเฮือนหลังหน้อยของแม่อุ้ย ตี้ยังตั้งอยู่", "เหลือก้าเฮือนหลังหน้อยของแม่อุ้ย ตี้ยังตั้งอยู่", "and her own little house, still standing."],
  W043: ["หัวหน้าหมู่บ้านนอกกำแปงเมืองได้ยินเสียง ก่อปากั๋นมาผ่อ", "หัวหน้าหมู่บ้านนอกกำแปงเมืองได้ยินเสียง ก่อปากั๋นมาผ่อ", "The village heads from outside the walls heard the roars, and came to see."],
  W044: ["หมู่เขาหันก้าน้ำ กับเฮือนของแม่อุ้ยแม่ฮ๊าง", "หมู่เขาหันก้าน้ำ กับเฮือนของแม่อุ้ยแม่ฮ๊าง", "They found only water, and the old widow's house."],
  W045: ["แม่อุ้ยเล่าเรื่องป๋าเหยี่ยนเผือก จายหนุ่ม ละก่อเสียงดังสามเตื้อหื้อฟัง", "แม่อุ้ยเล่าเรื่องป๋าเหยี่ยนเผือก จายหนุ่ม ละก่อเสียงดังสามเตื้อหื้อฟัง", "She told them about the eel, the young man, and the three roars."],
  W046: ["หมู่เขาถามว่า ป๋าเหยี่ยนตั๋วนั้นตั๋วหลวงม๊อกใด", "หมู่เขาถามว่า ป๋าเหยี่ยนตั๋วนั้นตั๋วหลวงม๊อกใด", "\"How big was the eel?\" they asked."],
  W047: ["แม่อุ้ยบ่าเคยหัน แต่เขาลากมันขึ้นมา ฮอยลากมันเลิ๊กจ๋นเป๋นฮ่องน้ำ", "แม่อุ้ยบ่าเคยหัน แต่เขาลากมันขึ้นมา ฮอยลากมันเลิ๊กจ๋นเป๋นฮ่องน้ำ", "\"I never saw it. But they dragged it so hard, it made a stream.\""],
  W048: ["ฮ่องน้ำนั้นเลยได้จื่อว่าแม่น้ำลาก", "ฮ่องน้ำนั้นเลยได้จื่อว่าแม่น้ำลาก", "And that stream is still called the Mae Nam Lak, the dragged river."],
  W049: ["หมู่เขาอู้กั๋นว่า หมู่เฮาผิดไปแต้แต้ตี้บะสนใจ๋คนเฒ่าคนแก่", "หมู่เขาอู้กั๋นว่า หมู่เฮาผิดไปแต้ๆตี้บะสนใจ๋คนเฒ่าคนแก่", "They said to each other, \"We were truly wrong not to listen to the old.\""],
  W050: ["เลยฮับแม่อุ้ยไปผ่อไปกอยอย่างดี เหมือนคนในครอบครัว", "เลยฮับแม่อุ้ยไปผ่อไปกอยอย่างดี เหมือนคนในครอบครัว", "They took her in, and cared for her as their own."],
  W051: ["แล้วหมู่เขา ก่อปรึกษากั๋น เลือกขุนลังเป๋นผู้นำ", "แล้วหมู่เขา ก่อปรึกษากั๋น เลือกขุนลังเป๋นผู้นำ", "Then they talked together, and chose a leader among them, Khun Lang."],
  W052: ["แล้วแป๋งเมืองแห๋มใหม่ฮิมน้ำโขง จื่อเวียงปรึกษา", "แล้วแป๋งเมืองแห๋มใหม่ฮิมน้ำโขง จื่อเวียงปรึกษา", "And they built a new town by the Mae Khong, and called it Wiang Prueksa, the town of talking together."],
  W053: ["กู๊วันนี้หนองน้ำแห่งนี้เก่าแก่ขนาด เก่าเหลือเมืองใด ละก่อแผ่นดินตั๊ดนี่ก่อไหวแต้", "กู๊วันนี้หนองน้ำแห่งนี้เก่าแก่ขนาด เก่าเหลือเมืองใด ละก่อแผ่นดินตั๊ดนี่ก่อไหวแต้", "Today the marsh is very old, far older than any city, and the ground here does sometimes shake."],
  W054: ["คนเปิ้นฮ้องเกาะหน้อยหน้อย ตี้ก๋างหนองว่าเกาะแม่ม่าย", "คนเปิ้นฮ้องเกาะหน้อยๆ ตี้ก๋างหนองว่าเกาะแม่ม่าย", "People call a little island in it Ko Mae Mai, the widow's island."],
  W055: ["แล้วจายหนุ่มคนนั้นลอ ต๋ำนานเก่าบ่าได้บอกว่าเขาเป๋นไผ", "แล้วจายหนุ่มคนนั้นลอ ต๋ำนานเก่าบ่าได้บอกว่าเขาเป๋นไผ", "And the young man? The old book never says who he was."],
  W056: ["บางคนก่อว่าเขาเป๋นพญานาค องค์เดียวกับตี้เกยบอกเจ้าชายหื้อแป๋งเมืองตั๊ดนี่", "บางคนก่อว่าเขาเป๋นพญานาค องค์เดียวกับตี้เกยบอกเจ้าชายหื้อแป๋งเมืองตั๊ดนี่", "Some say he was a naga, the same one who once told the prince to build his city here."],
  W057: ["สีท่าจะแม่นก่อได้ บ่ามีไผฮู้", "สีท่าจะแม่นก่อได้ บ่ามีไผฮู้", "Perhaps he was. No one knows."],
  W058: ["แต่ตี้หมู่เฮาฮู้คือ ขอหื้อมีจิตใจ๋เมตต๋า มีใจ๋ฮักคน ฮักสัตว์ตึงหมดตึงมวล ละก่อบะดีลืมคุณงามความดีของไผสักคน", "แต่ตี้หมู่เฮาฮู้คือ ขอหื้อมีจิตใจ๋เมตต๋า มีใจ๋ฮักคน ฮักสัตว์ตึงหมดตึงมวล ละก่อบะดีลืมคุณงามความดีของไผสักคน", "But this we know: be kind, love people and every animal, and never forget the good that anyone has done."],
};
